verus! {

    /// Returns the index of the last (rightmost) occurrence of the maximum
    /// element in a non-empty slice of i32.  The returned index is within
    /// bounds, its element is at least as large as every other element in
    /// the slice, and no element to its right is equal to it.
    fn mlast_maximum(v: &[i32]) -> usize
        requires
            v.len() > 0
        ensures
            // The result is a valid index
            |ret: usize| ret < v.len()
        ensures
            // Its element is a global maximum
            forall|k: usize| k < v.len() ==> v[k] <= v[ret]
        ensures
            // No equal maximum occurs strictly to the right
            forall|k: usize| k > ret && k < v.len() ==> v[k] < v[ret]
    {
        // max_idx is the index of the rightmost maximum seen so far
        let mut max_idx: usize = 0;
        let mut max_val: i32 = v[0];

        // j is the next position to examine
        let mut j: usize = 1;
        while j < v.len()
            invariant
                // j marches forward from 1 to v.len()
                1 <= j && j <= v.len()
            invariant
                // max_idx always points into [0, j)
                0 <= max_idx && max_idx < j
            invariant
                // max_val agrees with v[max_idx]
                max_val == v[max_idx]
            invariant
                // All elements before j are ≤ max_val
                forall|k: usize| k < j ==> v[k] <= max_val
            invariant
                // Among all positions < j where v[k] == max_val,
                // max_idx is the largest one (rightmost so far)
                forall|k: usize| k < j && v[k] == max_val ==> k <= max_idx
            decreases
                // ensures termination
                v.len() - j
        {
            let x = v[j];
            if x > max_val {
                // new strict maximum
                max_val = x;
                max_idx = j;
            } else if x == max_val {
                // equal to current maximum: take the rightmost
                max_idx = j;
            }
            j += 1;
        }

        // At exit, j == v.len(), so max_idx is the rightmost maximum
        max_idx
    }

}